function ownLoss(best,c){return Number.isFinite(best?.cp)&&Number.isFinite(c?.cp)?Math.max(0,best.cp-c.cp):(c===best?0:9999)}
function styleScore(p,f){if(!f)return 0;if(p.personality==='aggressive')return (f.capture?28:0)+(f.promote?22:0)+(f.check?38:0)+Math.max(0,f.advance||0)*8+Math.max(0,f.centerGain||0)*3+(f.major?7:0)-(f.replyChecks||0)*2;if(p.personality==='defensive')return (f.capture?7:0)-(f.replyChecks||0)*20+(f.develop?22:0)+(f.kingMove?14:0)-Math.max(0,f.advance||0)*2+(!f.check?4:0);if(p.personality==='stable')return (f.capture?6:0)-(f.replyChecks||0)*12-(f.check?4:0)+(f.develop?28:0)+(f.kingMove?10:0)+Math.max(0,f.centerGain||0)*2;if(p.personality==='positional')return (f.capture?4:0)+(f.develop?14:0)+Math.max(0,f.centerGain||0)*4-(f.replyChecks||0)*8+(f.kingMove?4:0)+(f.check?3:0);return (f.capture?8:0)+(f.promote?6:0)+(f.check?6:0)+(f.develop?8:0)+Math.max(0,f.centerGain||0)*2-(f.replyChecks||0)*4}
async function pick(s,res,p){const cs=(res?.info?.candidates||[]).filter(x=>x?.token).sort((a,b)=>(a.rank||99)-(b.rank||99));if(!cs.length)return{token:res?.info?.bestmove,rank:1,ownLoss:0,targetDistance:0};const best=cs[0];if(best?.mate!=null)return{token:best.token,rank:best.rank||1,ownLoss:0,targetDistance:0,forced:true};const pool=cs.filter(c=>ownLoss(best,c)<=p.maxLoss&&!(c?.mate!=null&&c.mate<0));let win=best,ws=-1e12,wf=null;for(const c of (pool.length?pool:[best])){const l=ownLoss(best,c),f=await page.evaluate(({s,u})=>window.__COHORT_TUNE_DIAG.flags(s,u),{s,u:c.token});const targetPenalty=Math.abs(l-p.targetLoss)*0.75;const rankPenalty=(Math.max(1,c.rank||1)-1)*1.5;const sc=styleScore(p,f)-targetPenalty-rankPenalty;if(sc>ws){ws=sc;win=c;wf=f}}return{token:win.token,rank:win.rank||1,ownLoss:ownLoss(best,win),targetDistance:Math.abs(ownLoss(best,win)-p.targetLoss),flags:wf}}
const stats=Object.fromEntries(target.map(x=>[x.i,{...x,tests:0,exact:0,top5:0,outside:0,deepLoss:[],ownLoss:[],elapsed:[]} ]));const mama={tests:0,exact:0,top5:0,outside:0,deepLoss:[],elapsed:[]};
